          answerEn: "The list is probably connected to a lesson or lessons about time or a text about someone's relationship with time. A possible organisation might include bringing the clock words together in a word-map or bubble diagram (clock, wristwatch, hands, minute-hand); other words could then be added later (hour-hand, face/dial, digital, etc.). Tell the time and What time do you make it? could form a separate list of 'time phrases', to which others could be added, e.g. Have you got the time?, My watch is fast/slow, etc. Drowsy and wide awake could be treated as antonyms, and some notes about the usage of beneath and under would be useful. This list could have information about word-class too.",
          answerFa: "این فهرست احتمالاً به درس یا درس‌هایی درباره زمان یا متنی درباره رابطهٔ کسی با زمان مرتبط است. یک سازماندهی ممکن شامل جمع‌آوری واژه‌های ساعت در یک نقشهٔ واژگان یا دیاگرام حباب باشد (ساعت، مچ‌بند، عقربه‌ها، عقربهٔ دقیقه)؛ سپس می‌توان واژه‌های دیگر را بعداً اضافه کرد (عقربهٔ ساعت، صفحه/رویه، دیجیتال و غیره). «ساعت را بگو» و «چند ساعت است؟» می‌توانند فهرست جداگانه‌ای از «عبارات زمان» تشکیل دهند، به سایر عبارات نیز می‌توان اضافه کرد، مثلاً «وقت را دارید؟»، «ساعت من سریع/کند است» و غیره. خواب‌آلود و کاملاً بیدار را می‌توان به عنوان متضاد در نظر گرفت و برخی نکات در مورد کاربرد beneath و under مفید خواهد بود. این فهرست می‌تواند اطلاعاتی دربارهٔ ردهٔ واژگانی (word-class) نیز داشته باشد."
