          answerEn: "noun: production, industry, export | verb: produce, industrialise, export | adjective: productive, industrial, export | person: producer, industrialist, exporter. Note the change in stress from export (noun or adjective) to export (verb) and exporter (person), e.g. Our export figures have increased; we exported 20% more goods last year.",
