          answerFa: "تکیه‌کلمه روی هجای زیرخط‌کشیده در هر کلمه در جدول است. | فعل: convert, produce, conduct, impress, support, impose | اسم شخص: convert, producer, conductor, –, supporter, – | صفت: converted, productive, conducive, impressive, supportive, imposing | اسم انتزاعی: conversion, production, produce, product, productivity, conduct, conduction, impression, support, imposition"
